/**
 * Sistema centralizado de traducciones para PlugsEssentials
 * Soporta español (es) e inglés (en)
 */

const DEFAULT_LANG = 'es';

/**
 * Obtiene el idioma configurado del jugador
 * @param {Player} player - El jugador
 * @returns {string} Código de idioma ('es' o 'en')
 */
export function getPlayerLanguage(player) {
    try {
        const settingsData = player.getDynamicProperty("playerSettings");
        if (settingsData) {
            const settings = JSON.parse(settingsData);
            return settings.language || DEFAULT_LANG;
        }
    } catch (e) {
        // Si hay error, usar idioma por defecto
    }
    return DEFAULT_LANG;
}

/**
 * Obtiene un texto traducido con fallback a personalización de admin
 * @param {string} lang - Código de idioma
 * @param {string} key - Clave del texto
 * @param {string|null} customText - Texto personalizado por admin (opcional)
 * @returns {string} Texto traducido o personalizado
 */
export function getText(lang, key, customText = null) {
    // Si hay texto personalizado, usarlo (ignora idioma)
    if (customText !== null && customText !== undefined && customText !== '') {
        return customText;
    }
    
    // Buscar en traducciones
    const parts = key.split('.');
    let current = TRANSLATIONS[lang] || TRANSLATIONS[DEFAULT_LANG];
    
    for (const part of parts) {
        if (current && current[part] !== undefined) {
            current = current[part];
        } else {
            // Fallback al idioma por defecto si no existe la traducción
            current = TRANSLATIONS[DEFAULT_LANG];
            for (const p of parts) {
                if (current && current[p] !== undefined) {
                    current = current[p];
                } else {
                    return `[Missing: ${key}]`;
                }
            }
            break;
        }
    }
    
    return current;
}

/**
 * Nombres de unidades de tiempo para formateo
 */
export const UNIT_NAMES = {
    es: {
        year: 'año',
        month: 'mes',
        week: 'semana',
        day: 'día',
        hour: 'hora',
        minute: 'minuto',
        second: 'segundo',
        ms: 'ms'
    },
    en: {
        year: 'year',
        month: 'month',
        week: 'week',
        day: 'day',
        hour: 'hour',
        minute: 'minute',
        second: 'second',
        ms: 'ms'
    }
};

